{
  "items": [
    {
      "name": "Polynomial.as_sum_range'",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  p.natDegree < n → p = ∑ i ∈ Finset.range n, (Polynomial.monomial i) (p.coeff i)"
    },
    {
      "name": "Polynomial.as_sum_range",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R),\n  p = ∑ i ∈ Finset.range (p.natDegree + 1), (Polynomial.monomial i) (p.coeff i)"
    },
    {
      "name": "Polynomial.as_sum_range_C_mul_X_pow'",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R) {n : ℕ},\n  p.natDegree < n → p = ∑ i ∈ Finset.range n, Polynomial.C (p.coeff i) * Polynomial.X ^ i"
    },
    {
      "name": "Polynomial.as_sum_range_C_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Support",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (p : Polynomial R),\n  p = ∑ i ∈ Finset.range (p.natDegree + 1), Polynomial.C (p.coeff i) * Polynomial.X ^ i"
    },
    {
      "name": "Polynomial.coeff_eq_zero_of_degree_lt",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} {n : ℕ} [inst : Semiring R] {p : Polynomial R}, p.degree < ↑n → p.coeff n = 0"
    }
  ]
}
